    ':null,"inn":[],"ut":[],"kilde":"Oppdatert etter Reimers A, Berg JA, Burns ML, Johannessen Landmark C. Felles referanseområder for antiepileptika. Tidsskr Nor Legeforen 2017; 137: 864–5: de nasjonale referanseområdene fra 2017 står nå i grunnlaget for referanseområdet"},{"kode":"LAM","side":null,"panel":"viktige_data","elementtype":"referanseomrade","tittel":null,"fra":{"nedre":10,"ovre":50,"enhet"'
    ':"µmol/L"},"til":{"nedre":10,"ovre":50},"inn":["reimers2017"],"ut":[],"kilde":"Oppdatert etter Reimers A, Berg JA, Burns ML, Johannessen Landmark C. Felles referanseområder for antiepileptika. Tidsskr Nor Legeforen 2017; 137: 864–5: det nasjonale referanseområdet fra 2017 er det samme, 10–50 µmol/L"},{"kode":"LAM","side":null,"panel":"tdm","elementtype":"kinetikkort","tittel":"Grunnlag for referan'
    'seområdet","fra":{"dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Referanseområdene for antiepileptika ble ikke beregnet på nytt i prosjektet. Diakonhjemmet sykehus tok i 2008 i bruk området St. Olavs hospital har utarbeidet sammen med nevrologisk avdeling der. Statens senter for epilepsi brukte da 10–60 µmol/L."}]}]}},"til":{"dokument":{"type":"doc","cont'
    'ent":[{"type":"paragraph","content":[{"type":"text","text":"Referanseområdet er det felles nasjonale referanseområdet for antiepileptika fra 2017, som styret i Norsk forening for klinisk farmakologi har godkjent. Det gjelder prøver tatt medikamentfastende, det vil si like før neste ordinære dose og 12–24 timer etter forrige inntak."}]},{"type":"paragraph","content":[{"type":"text","text":"I 2017 b'
    'le området harmonisert til 10–50 µmol/L. Laboratoriene brukte før det 10–50 eller 10–60 µmol/L."}]},{"type":"paragraph","content":[{"type":"text","text":"Før 2017 bygde området på referanseområdeprosjektet (2008):"}]},{"type":"paragraph","content":[{"type":"text","text":"Referanseområdene for antiepileptika ble ikke beregnet på nytt i prosjektet. Diakonhjemmet sykehus tok i 2008 i bruk området St.'
    ' Olavs hospital har utarbeidet sammen med nevrologisk avdeling der. Statens senter for epilepsi brukte da 10–60 µmol/L."}]}]}},"inn":["reimers2017"],"ut":[],"kilde":"Oppdatert etter Reimers A, Berg JA, Burns ML, Johannessen Landmark C. Felles referanseområder for antiepileptika. Tidsskr Nor Legeforen 2017; 137: 864–5: grunnlaget er de felles nasjonale referanseområdene for antiepileptika fra 2017"'
    '},{"kode":"CZP","side":null,"panel":"tdm","elementtype":"kinetikkort","tittel":"Referansegrense","fra":{"dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Øvre referansegrense 50 nmol/L er den øvre forventede medikamentfastende konsentrasjonen ved døgndose 1,5 mg, høyeste døgndose ved angst, uro og/eller søvnvansker."}]},{"type":"paragraph","content":[{"type"'
    ':"text","text":"Ved epilepsi brukes høyere doser, og referanseområdet er da 60–220 nmol/L."}]},{"type":"paragraph","content":[{"type":"text","text":"Det er ikke satt noen nedre grense, siden konsentrasjonen bør holdes så lav som mulig. Lavest mulig dosering og kortvarig eller periodevis bruk bør tilstrebes."}]}]}},"til":{"dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"t'
    'ext","text":"Øvre referansegrense 50 nmol/L er den øvre forventede medikamentfastende konsentrasjonen ved døgndose 1,5 mg, høyeste døgndose ved angst, uro og/eller søvnvansker."}]},{"type":"paragraph","content":[{"type":"text","text":"Ved epilepsi brukes høyere doser, og referanseområdet er da 40–120 nmol/L. Det er det felles nasjonale referanseområdet for antiepileptika fra 2017; før det var områ'
    'det 60–220 nmol/L."}]},{"type":"paragraph","content":[{"type":"text","text":"Det er ikke satt noen nedre grense, siden konsentrasjonen bør holdes så lav som mulig. Lavest mulig dosering og kortvarig eller periodevis bruk bør tilstrebes."}]}]}},"inn":["reimers2017"],"ut":[],"kilde":"Oppdatert etter Reimers A, Berg JA, Burns ML, Johannessen Landmark C. Felles referanseområder for antiepileptika. Tid'
    'sskr Nor Legeforen 2017; 137: 864–5: referanseområdet ved epilepsi er 40–120 nmol/L, ikke 60–220 nmol/L"}]'::jsonb) loop
    -- Kortet på siden, der feltene står nøyaktig som oppgitt, uten upublisert utkast.
    select u.objekt_id, u.revisjon, r.innhold into e
    from public.innholdselementer t
    join public.objekttilstander u on u.objekt_id = t.objekt_id and u.tilstand = 'utkast'
    join public.objekttilstander p on p.objekt_id = t.objekt_id and p.tilstand = 'publisert' and p.revisjon = u.revisjon
    join public.objektrevisjoner r on r.objekt_id = t.objekt_id and r.revisjon = u.revisjon
    where t.tilstand = 'publisert'
      and t.infoside_id = coalesce(
        (select a.hovedside_id from public.laboratorieanalytter a where a.tilstand = 'publisert' and a.kode = oppdatering->>'kode'),
        (select s.objekt_id from public.infosider s where s.tilstand = 'publisert' and lower(s.navn) = lower(oppdatering->>'side')))
      and t.panel = oppdatering->>'panel' and t.elementtype = oppdatering->>'elementtype'
      and (t.data->>'tittel') is not distinct from (oppdatering->>'tittel')
      and not exists (
        select 1 from jsonb_each(oppdatering->'fra') f where r.innhold->'data'->f.key is distinct from f.value)
    order by t.posisjon, t.objekt_id
    limit 1;
    if not found then
      raise notice 'Oppdaterer ikke % på %: fant ikke kortet slik det var, eller det har et upublisert utkast.',
        coalesce(oppdatering->>'tittel', oppdatering->>'elementtype'), coalesce(oppdatering->>'kode', oppdatering->>'side');
      continue;
    end if;

    -- De nye kildene først, så de som sto fra før og ikke tas bort.
    select coalesce(jsonb_agg(k order by rekke, i), '[]'::jsonb) into kilder
    from (
      select to_jsonb(kildenokler->>n) as k, 0 as rekke, i
        from jsonb_array_elements_text(oppdatering->'inn') with ordinality as inn(n, i)
      union all
      select x, 1, i
        from jsonb_array_elements(coalesce(e.innhold->'referanser', '[]')) with ordinality as fra(x, i)
        where not exists (select 1 from jsonb_array_elements_text(oppdatering->'inn') n where to_jsonb(kildenokler->>n) = x)
          and not exists (select 1 from jsonb_array_elements_text(oppdatering->'ut') n where to_jsonb(kildenokler->>n) = x)
    ) alle;

    ny := case when jsonb_typeof(oppdatering->'til') = 'null'
      then jsonb_set(e.innhold, '{panel}', to_jsonb('fjernet'::text))
      else e.innhold || jsonb_build_object('data', (e.innhold->'data') || (oppdatering->'til'), 'referanser', kilder)
    end;
    -- Står kortet alt slik oppdateringen gir det, lages ingen ny revisjon.
    continue when ny = e.innhold;

    perform set_config('far.revisjonskilde', oppdatering->>'kilde', true);
    perform public.lagre_utkast(e.objekt_id, e.revisjon, ny);
    perform public.publiser_utkast(e.objekt_id, e.revisjon + 1);
  end loop;
end
$oppdatering$;